from repository import TenantRepository
from router import TenantRouter
from shard_directory import ShardDirectoryRecord
from tenant_models import context


def repo():
    return TenantRepository(TenantRouter(ShardDirectoryRecord("dir", metadata={"shards": ["s0", "s1", "s2", "s3"]})))


def test_same_tenant_routes_same_shard_for_different_users():
    r = repo().router
    assert r.route(context("t1", "u1"))["shard"] == r.route(context("t1", "u2"))["shard"]


def test_different_request_ids_do_not_change_route():
    r = repo().router
    assert r.route(context("t1", "u1", "r1"))["shard"] == r.route(context("t1", "u1", "r2"))["shard"]


def test_write_then_read_with_same_user_returns_record():
    rp = repo(); ctx = context("t1", "u1")
    rp.write(ctx, "invoice-1", {"total": 20})
    assert rp.read(ctx, "invoice-1") == {"total": 20}


def test_write_then_read_with_different_user_same_tenant_returns_record():
    rp = repo()
    rp.write(context("t1", "u1"), "invoice-1", {"total": 20})
    assert rp.read(context("t1", "u2"), "invoice-1") == {"total": 20}


def test_preview_omits_user_id():
    assert "user_id" not in repo().router.preview(context("t1", "u1"))


def test_preview_keys_are_stable():
    assert set(repo().router.preview(context("t1"))) == {"tenant_id", "shard", "slot"}


def test_route_keys_are_stable():
    assert set(repo().router.route(context("t1"))) == {"tenant_id", "user_id", "shard", "slot"}


def test_repository_write_response_keys_are_stable():
    assert set(repo().write(context("t1"), "k", {})) == {"ok", "tenant_id", "key", "shard"}


def test_records_for_different_tenants_do_not_collide():
    rp = repo()
    rp.write(context("t1"), "settings", {"theme": "dark"})
    rp.write(context("t2"), "settings", {"theme": "light"})
    assert rp.read(context("t1"), "settings") == {"theme": "dark"}


def test_common_wrong_fix_does_not_route_by_user_hash():
    r = repo().router
    shards = {r.route(context("tenant-x", f"user-{i}"))["shard"] for i in range(8)}
    assert len(shards) == 1


def test_route_slot_is_within_shard_range():
    route = repo().router.route(context("t1"))
    assert 0 <= route["slot"] < 4


def test_write_uses_tenant_prefix_in_storage_key():
    rp = repo(); response = rp.write(context("t1"), "k", {"v": 1})
    assert f"t1:k" in rp.storage[response["shard"]]


def test_read_missing_record_returns_none():
    assert repo().read(context("t1"), "missing") is None


def test_value_is_copied_on_write():
    rp = repo(); payload = {"v": 1}; rp.write(context("t1"), "k", payload); payload["v"] = 2
    assert rp.read(context("t1"), "k") == {"v": 1}


def test_tenant_id_is_preserved_in_route():
    assert repo().router.route(context("tenant-a"))["tenant_id"] == "tenant-a"


def test_user_id_is_preserved_for_authorization_context():
    assert repo().router.route(context("tenant-a", "user-a"))["user_id"] == "user-a"


def test_same_tenant_same_slot_for_many_users():
    r = repo().router
    assert len({r.route(context("t9", f"u{i}"))["slot"] for i in range(5)}) == 1


def test_diagnostic_preview_matches_write_shard():
    rp = repo(); ctx = context("t1", "u1")
    assert rp.router.preview(ctx)["shard"] == rp.write(ctx, "k", {})["shard"]


def test_read_uses_same_route_as_write_even_after_user_changes():
    rp = repo(); rp.write(context("t1", "writer"), "k", {"v": 1})
    assert rp.read(context("t1", "reader"), "k") == {"v": 1}


def test_empty_tenant_id_is_not_routed():
    try:
        repo().router.route(context(""))
    except ValueError:
        assert True
    else:
        assert False
